-- All data and audit fixtures roll back. No emails are sent.
begin;
do $$
declare actor uuid=gen_random_uuid(); limited uuid=gen_random_uuid(); t uuid; draft uuid; post uuid; team uuid; legacy_challenge uuid; data jsonb;
begin
  insert into public.officer_committee_invitations(email,name,modules) values('scoreboard-test@student.fatima.edu.ph','Scoreboard test',array['tournaments']);
  insert into auth.users(id,email) values(actor,'scoreboard-test@student.fatima.edu.ph');
  insert into public.officer_committee_invitations(email,name,modules) values('scoreboard-limited@student.fatima.edu.ph','Limited scoreboard test',array['content']);
  insert into auth.users(id,email) values(limited,'scoreboard-limited@student.fatima.edu.ph');
  insert into public.content(kind,slug,title,status,external_url) values('tournament','scoreboard-public-test','Published scoreboard test','published','https://example.com/bracket') returning id into t;
  insert into public.content(kind,slug,title,status) values('tournament','scoreboard-draft-test','Draft scoreboard test','draft') returning id into draft;
  insert into public.content(kind,slug,title,status) values('announcement','scoreboard-post-test','Not a tournament','published') returning id into post;
  perform set_config('request.jwt.claim.sub',actor::text,true); execute 'set local role authenticated';
  insert into public.tournament_scoreboard(tournament_id,team_name) values(t,'Test Phoenix') returning id into team;
  insert into public.tournament_scoreboard(tournament_id,team_name) values(draft,'Draft team');
  update public.tournament_scoreboard set team_name='Test Phoenix',version=2 where id=team and version=1;
  if not exists(select 1 from public.tournament_scoreboard where id=team and wins=0 and version=2) then raise exception 'FAIL scoreboard edit'; end if;
  begin update public.tournament_scoreboard set team_name='Stale name',version=2 where id=team; raise exception 'FAIL stale update'; exception when others then if sqlerrm like 'FAIL:%' then raise; end if; end;
  begin insert into public.tournament_scoreboard(tournament_id,team_name) values(t,' test PHOENIX '); raise exception 'FAIL duplicate team'; exception when unique_violation then null; end;
  begin insert into public.tournament_scoreboard(tournament_id,team_name,wins) values(t,'Negative wins',-1); raise exception 'FAIL negative wins'; exception when check_violation or insufficient_privilege then null; end;
  begin insert into public.tournament_scoreboard(tournament_id,team_name) values(post,'Wrong content'); raise exception 'FAIL non tournament'; exception when others then if sqlerrm like 'FAIL:%' then raise; end if; end;
  begin update public.tournament_scoreboard set tournament_id=draft,version=3 where id=team; raise exception 'FAIL reparent team'; exception when others then if sqlerrm like 'FAIL:%' then raise; end if; end;
  execute 'reset role';
  if not exists(select 1 from public.audit_log where record_id=team::text and actor_id=actor and reason like 'Updated scoreboard team: Test Phoenix%') then raise exception 'FAIL automatic scoreboard audit'; end if;
  execute 'set local role anon';
  if not exists(select 1 from public.tournament_scoreboard where id=team) then raise exception 'FAIL published scoreboard invisible'; end if;
  if exists(select 1 from public.tournament_scoreboard where tournament_id=draft) then raise exception 'FAIL draft scoreboard public'; end if;
  begin insert into public.tournament_scoreboard(tournament_id,team_name) values(t,'Public write'); raise exception 'FAIL anonymous scoreboard insert'; exception when insufficient_privilege then null; end;
  execute 'reset role'; perform set_config('request.jwt.claim.sub',limited::text,true); execute 'set local role authenticated';
  begin insert into public.tournament_scoreboard(tournament_id,team_name) values(t,'Unauthorized write'); raise exception 'FAIL module bypass'; exception when insufficient_privilege then null; end;
  begin update public.tournament_scoreboard set wins=100,version=3 where id=team; raise exception 'FAIL manual aggregate write'; exception when insufficient_privilege then null; end;
  if exists(select 1 from public.tournament_scoreboard where id=team and wins=100) then raise exception 'FAIL module update bypass'; end if;
  execute 'reset role';
  begin perform public.create_challenge('closed-test@student.fatima.edu.ph','team',t,'test'); raise exception 'FAIL tournament code creation'; exception when others then if sqlerrm like 'FAIL:%' then raise; end if; end;
  begin insert into public.teams(tournament_id,name,email,captain,roster) values(t,'Legacy team','closed-test@student.fatima.edu.ph','Captain','[]'); raise exception 'FAIL legacy team insertion'; exception when others then if sqlerrm like 'FAIL:%' then raise; end if; end;
  insert into private.email_challenges(email,purpose,target_id,code_hash) values('old-team-token@student.fatima.edu.ph','team',t,'legacy-code') returning id into legacy_challenge;
  perform public.verify_challenge(legacy_challenge,'legacy-code','legacy-grant');
  begin perform public.submit_verified(legacy_challenge,'legacy-grant','legacy-token',jsonb_build_object('name','Legacy registration')); raise exception 'FAIL stale tournament grant accepted'; exception when others then if sqlerrm like 'FAIL:%' then raise; end if; end;
  begin perform public.generate_bracket(t,actor,'test'); raise exception 'FAIL internal bracket generation'; exception when others then if sqlerrm like 'FAIL:%' then raise; end if; end;
  begin perform public.record_result(gen_random_uuid(),actor,1,2,0,'test'); raise exception 'FAIL internal result entry'; exception when others then if sqlerrm like 'FAIL:%' then raise; end if; end;
  perform set_config('request.jwt.claim.sub',actor::text,true); execute 'set local role authenticated';
  update public.content set status='archived' where id=t;
  execute 'reset role'; execute 'set local role anon';
  if exists(select 1 from public.tournament_scoreboard where id=team) then raise exception 'FAIL archived scoreboard public'; end if;
  execute 'reset role'; perform set_config('request.jwt.claim.sub',actor::text,true); execute 'set local role authenticated';
  delete from public.tournament_scoreboard where id=team and version=2;
  execute 'reset role';
  if not exists(select 1 from public.audit_log where record_id=team::text and action='delete' and actor_id=actor) then raise exception 'FAIL scoreboard deletion audit'; end if;
end $$;
rollback;
